using System;
using System.Drawing;
using WoWProbe;
class QuickRecoveryTests
{
    static int passed,failed;
    static void Check(bool b){if(!b)throw new Exception("Unexpected recovery behavior");}
    static OperationObservation O(){return new OperationObservation{Sequence=1,Fresh=true,GeometryKnown=true,ReleaseKnown=true,ReleaseVisible=true,ReleaseEnabled=true,ReleaseRegion=new Rectangle(100,100,100,30),ResurrectKnown=true,ResurrectRegion=new Rectangle(200,100,100,30),RecoveryDelayKnown=true,RecoveryDelayMs=0,CorpseKnown=true,CorpseX=.35,CorpseY=.52,Farm=new FarmObservation{Fresh=true,KnownCore=true,MapId=1432,MapMode=1,Zone="test",PlayerDead=true,Health=0,X=.32,Y=.47,Facing=0,Sequence=1}};}
    static QuickRecovery Engine(OperationObservation o,bool actual=false){var r=new RouteDocument{RouteId="test",Name="test",RouteType="corpse_run",MapId=1432,MapMode=1,Zone="test"};r.Points.Add(new Waypoint{X=.32,Y=.47});r.Points.Add(new Waypoint{X=.344,Y=.512});return new QuickRecovery(r,new NavigationCalibration{MapId=1432,MapMode=1,Zone="test",TurnRadiansPerSecond=5.85},o.Farm,actual);}
    static QuickRecoveryCommand Step(QuickRecovery e,OperationObservation o,long now){o.Sequence++;o.Farm.Sequence=o.Sequence;return e.Step(o,now);}
    static void Test(string name,Action body){try{body();passed++;Console.WriteLine("PASS "+name);}catch(Exception ex){failed++;Console.WriteLine("FAIL "+name+": "+ex.Message);}}
    static int Main()
    {
        Test("distant corpse follows recorded endpoint before final corpse approach",()=>{var o=O();o.Farm.PlayerGhost=true;o.CorpseX=.60;o.CorpseY=.50;var r=new RouteDocument{RouteId="recorded-ghost",Name="ghost",RouteType="corpse_run",MapId=1432,MapMode=1,Zone="test"};r.Points.Add(new Waypoint{X=.32,Y=.47});r.Points.Add(new Waypoint{X=.32,Y=.50});r.Points.Add(new Waypoint{X=.34,Y=.50});var c=new NavigationCalibration{MapId=1432,MapMode=1,Zone="test"};var e=new QuickRecovery(r,c,o.Farm,true);Check(Step(e,o,0).Action!=QuickRecoveryAction.Stop);var nav=(Navigator)typeof(QuickRecovery).GetField("navigator",System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic).GetValue(e);var points=nav.WorkingRoute.Points;Check(points.Count>=4&&points[points.Count-2].X==.34&&points[points.Count-2].Y==.50);var last=points[points.Count-1];Check(last.X>.34&&last.X<o.CorpseX&&Math.Abs(NavigationMath.Distance(last.X-o.CorpseX,last.Y-o.CorpseY,c.AxisScale)-.008)<.000001);});
        Test("recorded ghost route preserves obstacle corners and resumes from a nearer route point",()=>{var o=O();o.Farm.PlayerGhost=true;o.CorpseX=.34;o.CorpseY=.49;var r=new RouteDocument{RouteId="recorded-ghost",Name="ghost",RouteType="corpse_run",MapId=1432,MapMode=1,Zone="test"};r.Points.Add(new Waypoint{X=.32,Y=.47});r.Points.Add(new Waypoint{X=.32,Y=.50});r.Points.Add(new Waypoint{X=.34,Y=.50});var c=new NavigationCalibration{MapId=1432,MapMode=1,Zone="test"};var e=new QuickRecovery(r,c,o.Farm,true);Step(e,o,0);var nav=(Navigator)typeof(QuickRecovery).GetField("navigator",System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic).GetValue(e);Check(nav.WorkingRoute.Points.Exists(w=>w.X==.32&&w.Y==.50));o.Farm.X=.34;o.Farm.Y=.50;e=new QuickRecovery(r,c,o.Farm,true);Check(Step(e,o,0).Action!=QuickRecoveryAction.Stop);nav=(Navigator)typeof(QuickRecovery).GetField("navigator",System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic).GetValue(e);Check(nav.WorkingRoute.Points[0].X==.34&&!nav.WorkingRoute.Points.Exists(w=>w.Y==.47));});
        Test("startup route availability agrees with map mode zone and corpse purpose",()=>{var o=O().Farm;var r=new RouteDocument{RouteType="corpse_run",MapId=o.MapId,MapMode=o.MapMode,Zone=o.Zone};Check(QuickRecovery.RouteMatches(r,o));r.MapId++;Check(!QuickRecovery.RouteMatches(r,o));r.MapId=o.MapId;r.MapMode++;Check(!QuickRecovery.RouteMatches(r,o));r.MapMode=o.MapMode;r.Zone="another";Check(!QuickRecovery.RouteMatches(r,o));r.Zone=o.Zone;r.RouteType="farm";Check(!QuickRecovery.RouteMatches(r,o));Check(!QuickRecovery.RouteMatches(null,o));});
        Test("release is a single click in the observed button and ghost travel follows",()=>{var o=O();var e=Engine(o);var c=Step(e,o,0);Check(c.Action==QuickRecoveryAction.Click&&c.Release&&QuickRecovery.Matches(c,o));Check(Step(e,o,1000).Action==QuickRecoveryAction.None);o.Farm.PlayerGhost=true;Check(!QuickRecovery.Matches(c,o));Check(Step(e,o,2000).Action==QuickRecoveryAction.None);Check(Step(e,o,2200).Action!=QuickRecoveryAction.Stop);});
        Test("known zero cooldown and actual button are required to resurrect",()=>{var o=O();o.Farm.PlayerGhost=true;o.Farm.X=.344;o.Farm.Y=.512;var e=Engine(o);o.ResurrectVisible=o.ResurrectEnabled=true;o.RecoveryDelayMs=30000;Check(Step(e,o,0).Action!=QuickRecoveryAction.Click);o.RecoveryDelayMs=0;var c=Step(e,o,1000);Check(c.Action==QuickRecoveryAction.Click&&!c.Release&&QuickRecovery.Matches(c,o));o.ResurrectRegion=new Rectangle(20,20,40,40);Check(!QuickRecovery.Matches(c,o));});
        Test("two distinct positive living frames complete recovery",()=>{var o=O();var e=Engine(o);o.Farm.PlayerDead=false;o.Farm.Health=50;Check(Step(e,o,0).Action==QuickRecoveryAction.None);Check(e.Step(o,40).Action==QuickRecoveryAction.None);Check(Step(e,o,200).Action==QuickRecoveryAction.Complete);});
        Test("unknown corpse stale packets wrong maps and different graveyards stop",()=>{for(int i=0;i<4;i++){var o=O();o.Farm.PlayerGhost=true;var e=Engine(o);if(i==0)o.CorpseKnown=false;if(i==1)o.Fresh=false;if(i==2)o.Farm.MapId++;if(i==3)o.Farm.X=.5;Check(Step(e,o,0).Action==QuickRecoveryAction.Stop);}});
        Test("corpse identity cannot move during the same recovery and clicks time out",()=>{var o=O();o.Farm.PlayerGhost=true;var e=Engine(o);Step(e,o,0);o.CorpseX+=.01;Check(Step(e,o,200).Action==QuickRecoveryAction.Stop);o=O();e=Engine(o);Step(e,o,0);Check(Step(e,o,11000).Action==QuickRecoveryAction.Stop);});
        Test("actual corpse mode stays ghost past the healer and revives only near the body",()=>{var o=O();o.Farm.PlayerGhost=true;o.CorpseY=.30;o.IncomingResurrectionKnown=o.IncomingResurrection=true;var e=Engine(o,true);Check(Step(e,o,0).Action!=QuickRecoveryAction.Stop);Check(Step(e,o,100).Action!=QuickRecoveryAction.Click);o.Farm.X=o.CorpseX;o.Farm.Y=o.CorpseY;o.ResurrectVisible=o.ResurrectEnabled=true;var c=Step(e,o,200);Check(c.Action==QuickRecoveryAction.Click&&!c.Release);o.Farm.PlayerDead=o.Farm.PlayerGhost=false;o.Farm.Health=20;Step(e,o,300);Check(Step(e,o,400).Action==QuickRecoveryAction.Complete);var combat=new QuickCombat(o.Farm,750);o.Farm.CastingKnown=true;Check(combat.Step(o.Farm,500).Action==QuickAction.Food);});
        Test("actual corpse mode never guesses unknown corpse positions or accepts another map",()=>{var o=O();o.Farm.PlayerGhost=true;o.CorpseKnown=false;var e=Engine(o,true);Check(Step(e,o,0).Action==QuickRecoveryAction.Stop);o=O();o.Farm.PlayerGhost=true;e=Engine(o,true);o.Farm.MapId++;Check(Step(e,o,0).Action==QuickRecoveryAction.Stop);});
        Test("recorded death point is sufficient without a pre-recorded graveyard route",()=>{var o=O();o.Farm.X=o.CorpseX;o.Farm.Y=o.CorpseY;var c=new NavigationCalibration{MapId=1432,MapMode=1,Zone="test"};var e=new QuickRecovery(null,c,o.Farm,true);Check(Step(e,o,0).Release);o.Farm.PlayerGhost=true;o.Farm.X=.32;o.Farm.Y=.47;o.CorpseKnown=false;Check(Step(e,o,1000).Action!=QuickRecoveryAction.Stop);});
        Test("continuous runs permit occasional deaths throughout the night but bound repeated failures",()=>{var rate=new QuickDeathRate();for(long t=0;t<8*3600000;t+=1200000)Check(rate.TryRecover(t));rate=new QuickDeathRate();Check(rate.TryRecover(0)&&rate.TryRecover(1000)&&rate.TryRecover(2000)&&!rate.TryRecover(3000)&&rate.TryRecover(600001));});
        Console.WriteLine("Quick recovery tests: "+passed+" passed, "+failed+" failed. Simulated observations only.");return failed==0?0:1;
    }
}
